INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das duale Studium nur in Deutschland üblich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in anderen Ländern"}, {"text": "Ja", "correct": false, "because": "International verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das duale Studium?', 3, '[{"text": "Praxis und Theorie kombinieren", "correct": true, "because": "Berufserfahrung und Abschluss"}, {"text": "Nur Theorie vermitteln", "correct": false, "because": "Praxis zentral"}, {"text": "Kosten sparen", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente umfasst ein duales Studium?', 5, '[{"text": "Hochschulstudium", "correct": true, "because": "Theoretische Bildung"}, {"text": "Praktische Ausbildung", "correct": true, "because": "Unternehmenspraxis"}, {"text": "Nur Prüfungen", "correct": false, "because": "Mehr als Prüfungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das duale Studium führt zu einem akademischen Abschluss. b) Es ist nur für Informatik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Fachrichtungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem dualen Studium?', 4, '[{"text": "Praxisphasen", "correct": false, "because": "Kernbestandteil"}, {"text": "Theoretische Module", "correct": false, "because": "Studiumsteil"}, {"text": "Papierdesign", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein duales Studium immer bezahlt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Unternehmenabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Abschlüsse kann man im dualen Studium erlangen?', 3, '[{"text": "Bachelor", "correct": true, "because": "Häufigster Abschluss"}, {"text": "Doktor", "correct": false, "because": "Zu hoch"}, {"text": "Schulabschluss", "correct": false, "because": "Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein duales Studium?', 5, '[{"text": "Praxisnähe", "correct": true, "because": "Berufserfahrung"}, {"text": "Schneller Berufseinstieg", "correct": true, "because": "Direkt einsatzbereit"}, {"text": "Nur Theorie", "correct": false, "because": "Praxis zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein duales Studium kombiniert Arbeit und Studium. b) Es dauert kürzer als ein normales Studium. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauer oft gleich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein duales Studium?', 4, '[{"text": "Kooperationsunternehmen", "correct": false, "because": "Praxispartner nötig"}, {"text": "Hochschule", "correct": false, "because": "Theorie nötig"}, {"text": "Papierarchiv", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein duales Studium nur für technische Studiengänge?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Wirtschaft, Soziales"}, {"text": "Ja", "correct": false, "because": "Viele Richtungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gibt es im dualen Studium?', 4, '[{"text": "Theoriephasen", "correct": true, "because": "Hochschule"}, {"text": "Praxisphasen", "correct": true, "because": "Unternehmen"}, {"text": "Urlaubsphasen", "correct": false, "because": "Kein Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein duales Studium keine Prüfungen hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Prüfungen Teil des Studiums"}, {"text": "Ja", "correct": false, "because": "Akademische Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem dualen Studium?', 3, '[{"text": "Zeitmanagement", "correct": true, "because": "Theorie und Praxis balancieren"}, {"text": "Papierqualität", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein duales Studium bietet Berufserfahrung. b) Es ist nur für Abiturienten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Zugänge"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmen bieten duale Studiengänge an?', 5, '[{"text": "IT-Firmen", "correct": true, "because": "Z. B. Fachinformatiker"}, {"text": "Industrieunternehmen", "correct": true, "because": "Z. B. Ingenieure"}, {"text": "Nur Schulen", "correct": false, "because": "Unternehmen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim dualen Studium unwichtig?', 3, '[{"text": "Kooperation", "correct": false, "because": "Partner essenziell"}, {"text": "Praxisbezug", "correct": false, "because": "Kernmerkmal"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein duales Studium kürzer als eine klassische Ausbildung?', 3, '[{"text": "Nein", "correct": true, "because": "Oft 3-4 Jahre"}, {"text": "Ja", "correct": false, "because": "Ähnliche Dauer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein duales Studium finanziert wird?', 2, '[{"text": "Ja", "correct": true, "because": "Oft vom Unternehmen"}, {"text": "Nein", "correct": false, "because": "Häufig bezahlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für ein duales Studium zentral?', 4, '[{"text": "Praxis-Theorie-Verknüpfung", "correct": true, "because": "Kernkonzept"}, {"text": "Nur Theorie", "correct": false, "because": "Praxis fehlt"}, {"text": "Papierdokumente", "correct": false, "because": "Digital ausreichend"}]');
